sys_ux_data_broker_scriptlet.required_translations:
[ {
  "message" : "Table",
  "comment" : ""
}, {
  "message" : "Table to look up",
  "comment" : ""
}, {
  "message" : "View",
  "comment" : ""
}, {
  "message" : "view to look up",
  "comment" : ""
} ]

sys_ux_data_broker_scriptlet.script:
(function () {
    /**
     * Fetches field metadata for a given table and view without using GlideTableHierarchy.
     * @param {Object} input - The input object containing the table name and optional view name.
     * @param {string} input.table - The name of the table to fetch fields for.
     * @param {string} [input.view] - The name of the view to filter fields by (optional).
     * @returns {Array} results - An array of field metadata objects.
     */
    function transform(input) {
        var results = [];

        // Validate input
        if (!input.table) {
            return results;
        }

        // Resolve all parent tables for the input table
        var parentTables = getParentTables(input.table);

        // Iterate through each table in the hierarchy
        for (var i = 0; i < parentTables.length; i++) {
            var table = parentTables[i];

            // Query sys_ui_element for fields in the given view
            var visibleFields = getVisibleFieldsForView(table, input.view);

            // Query sys_dictionary for all fields on the table
            var grSys = new GlideRecord('sys_dictionary');
            grSys.addEncodedQuery('name=' + table + '^internal_type!=collection^internal_typeISNOTEMPTY');
            grSys.query();

            while (grSys.next()) {
                var fieldName = grSys.getValue("element");

                // If view is specified, filter out fields not in the visibleFields list
                if (input.view && !visibleFields.includes(fieldName)) {
                    continue;
                }

                // Add the field metadata to the results
                results.push({
                    "column_label": grSys.getValue("column_label"),
                    "element": fieldName,
                    "reference": grSys.getValue("reference"),
                    "display": grSys.getValue("display"),
                    "type": grSys.getValue("internal_type")
                });
            }
        }

        return results;
    }

    /**
     * Gets all parent tables for the specified table.
     * @param {string} tableName - The name of the table.
     * @returns {Array} parentTables - An array of table names in the hierarchy.
     */
    function getParentTables(tableName) {
        var parentTables = [];
        var gr = new GlideRecord('sys_db_object');
        gr.addQuery('name', tableName);
        gr.query();

        if (gr.next()) {
            parentTables.push(tableName); // Add the current table
            var extendsTable = gr.getValue('super_class');
            while (extendsTable) {
                parentTables.push(extendsTable); // Add parent table
                var grParent = new GlideRecord('sys_db_object');
                grParent.addQuery('name', extendsTable);
                grParent.query();

                if (grParent.next()) {
                    extendsTable = grParent.getValue('super_class'); // Move to next parent
                } else {
                    extendsTable = null;
                }
            }
        }

        return parentTables;
    }

    /**
     * Gets all fields visible in the specified view for a table.
     * @param {string} table - The name of the table.
     * @param {string} view - The name of the view (optional).
     * @returns {Array} visibleFields - An array of field names visible in the view.
     */
    function getVisibleFieldsForView(table, view) {
        var visibleFields = [];
        if (!view) {
            return visibleFields; // Return empty if no view is specified
        }

        var grUiElement = new GlideRecord('sys_ui_element');
        grUiElement.addQuery('name', table);
        grUiElement.addQuery('view', view);
        grUiElement.query();

        while (grUiElement.next()) {
            visibleFields.push(grUiElement.getValue('element'));
        }

        return visibleFields;
    }

    // Execute and return the transformed results
    return transform(input);
})();
